'use strict';

class LRUCache {
  constructor(capacity) {
    if (typeof capacity !== 'number' || !Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError('capacity must be a positive integer');
    }
    this.capacity = capacity;
    this._map = new Map();
  }

  get(key) {
    if (!this._map.has(key)) {
      return undefined;
    }
    const value = this._map.get(key);
    // Refresh recency: move to most recently used position.
    this._map.delete(key);
    this._map.set(key, value);
    return value;
  }

  set(key, value) {
    // Delete first so updates refresh recency without changing size.
    this._map.delete(key);
    this._map.set(key, value);
    if (this._map.size > this.capacity) {
      // Evict the least recently used entry (first in iteration order).
      const lruKey = this._map.keys().next().value;
      this._map.delete(lruKey);
    }
    return this;
  }

  has(key) {
    return this._map.has(key);
  }

  delete(key) {
    return this._map.delete(key);
  }

  get size() {
    return this._map.size;
  }
}

module.exports = { LRUCache };

