node --test && node -e "
const { LRUCache } = require('./src/lru');
const assert = require('node:assert/strict');
// constructor validation
for (const bad of [0, -1, 1.5, Infinity, -Infinity, NaN, '2', undefined, null, {}, []]) {
  assert.throws(() => new LRUCache(bad), RangeError, JSON.stringify(bad));
}
// undefined value get refreshes recency
const c = new LRUCache(2);
c.set('a', undefined).set('b', 2);
assert.equal(c.get('a'), undefined); // refreshes 'a'
c.set('c', 3); // should evict 'b', not 'a'
assert.equal(c.has('a'), true);
assert.equal(c.has('b'), false);
// update doesn't evict unrelated / change size
const d = new LRUCache(2);
d.set('a', 1).set('b', 2);
d.set('a', 10);
assert.equal(d.size, 2);
assert.equal(d.get('b'), 2);
assert.equal(d.get('a'), 10);
// set returns this; capacity 1 edge
const e = new LRUCache(1);
e.set('x', 1).set('y', 2);
assert.equal(e.has('x'), false);
assert.equal(e.get('y'), 2);
// arbitrary keys (objects, NaN, -0/+0 Map semantics)
const f = new LRUCache(2);
const k = {};
f.set(k, 'obj').set(NaN, 'nan');
assert.equal(f.get(k), 'obj');
assert.equal(f.get(NaN), 'nan');
assert.equal(f.get(-0), undefined);
f.set(-0, 'zero');
f.set('e', 1); // evicts 'nan' (k refreshed by get)
assert.equal(f.get(-0), 'zero');
// independence
const g1 = new LRUCache(1), g2 = new LRUCache(1);
g1.set('a', 1);
assert.equal(g2.size, 0);
// delete preserves relative recency of survivors
const h = new LRUCache(2);
h.set('a', 1).set('b', 2).set('c', 3); // evicts a
assert.equal(h.delete('b'), true);
h.set('d', 4); // would evict b if present; evicts c
assert.equal(h.has('c'), false);
assert.equal(h.has('d'), true);
console.log('all extra checks passed');
"

